$('enter').onclick=()=>{if($('enter').disabled)return;if(!room){enterRoom();return}if(Math.hypot(avatar.position.x,avatar.position.z-10.3)<1.4){leaveRoom();return}const s=roomStops[activeStop];sheet=true;auto=false;padEnd();keys={};$('sheet').hidden=false;$('insideName').textContent=s.name;$('insideType').textContent=venues[roomIndex].name;$('insideHint').textContent=venues[roomIndex].kind==='market'?'攤商：今天的貨很新鮮，歡迎慢慢挑！（示意對話）':'查看這個生鮮區的商品，加入你的探索收藏。';$('categories').replaceChildren();showDetail(s.index,s.icon,s.name);if(s.icon!=='＋'){const key=roomIndex+':'+s.index;const collect=document.createElement('button');collect.className='collect-card';collect.textContent=collected.has(key)?'✓ 品項卡已收藏':'收集 '+s.icon+' 品項卡（試玩）';collect.disabled=collected.has(key);collect.onclick=()=>{collected.add(key);collect.disabled=true;collect.textContent='✓ 品項卡已收藏';$('collection').textContent='圖鑑 '+collected.size;toast('已收集 '+s.name+'，不扣點、不重複發獎。')};$('detail').appendChild(collect);const report=$('detail').querySelector('button');if(s.index!==0){report.disabled=submitted.has(key);report.textContent=submitted.has(key)?'待驗證（模擬）':'模擬拍照送審';report.onclick=()=>{submitted.add(key);report.disabled=true;report.textContent='待驗證（模擬）';toast('已加入本次試玩待審清單，再次開啟不會重複送出。')}}}};
